      await preload();
      return <><p>Async arrow preview {count}</p><main>{withRenderer<RowData>({
      render: (row: RowData) => <section>Typed row {row.name}{enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</section>,
