      const {
  account, rows, items, count, mode, enabled, fallback, selection, data,
  options, key, context, values, prototype, slots,
} = props;
      const ready = await preload();
      return <Shell ready={ready} preview={<p>Async preview {count}</p>}><main>{(() => {
      try {
        switch (mode) {
          case 'first': { const Value = LocalValue; return <Value>Local case {account?.profile?.displayName ?? fallback}</Value>; }
          case 'second': return <Choice branch={mode} first={account?.profile?.displayName ?? fallback} other="Second fallback" />;
          default: return <p>Default case {account?.profile?.displayName ?? fallback}</p>;
        }
      } catch (Choice) { return <Choice>Catch content {account?.profile?.displayName ?? fallback}</Choice>; }
      finally { record(<span>Finished {count}</span>); }
    })()}<p>After switch {account.name}</p></main></Shell>;
    }

